def dump(name, obj):
    (OUT/name).write_text(json.dumps(obj, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')

def md(name, text):
    (OUT/name).write_text(text.strip()+'\n', encoding='utf-8')

def envelope(kind, **kw):
    return dict(document_version=REV, schema='SDC-author-container-1.0', artifact_type=kind,
                status='AUTHOR_SUBMISSION', review_date=DATE, reviewer_instance=INSTANCE,
                authority='PROVISIONAL_INTERNAL_DOMAIN_AUTHORITY', synthetic_only=True,
                independent_approval=False, publication_status='NOT_PUBLISHED',
                human_validation=False, empirical_product_validation=False,
                clinical_clearance=False, foundation_status='0.2 CANDIDATE / NON-AUTHORITATIVE', **kw)

def recipe(id, sport, family, dose, equipment, stimulus, limits, **kw):
    proposed=kw.pop('proposed_support','APPROVE_WITH_CONDITIONS')
    return dict(recipe_id=id, revision=REV, sport=sport, family=family,
                dose=dose, equipment_AND=equipment, essential_stimulus=stimulus,
                limits=limits, origin='NEW_EXPLICIT_SYNTHETIC_REVIEW_CANDIDATE',
                runtime_catalog_exists=False, evidence_dose_status='CASE_SPECIFIC_EXEMPLAR_NOT_UNIVERSAL_MINIMUM_OR_OPTIMUM',
                proposed_disposition=proposed, **kw)

