def variant(id, branch, facts, action, level, preserve, modify, smaller, refs, disposition='APPROVE_WITH_CONDITIONS', evidence='SUPPORTED_WITH_LIMITS', **kw):
    v=dict(variant_id=id, revision=REV, branch=branch, facts=facts, proposed_disposition=disposition,
                author_state='AUTHOR_SUBMISSION', evidence_status=evidence,
                proposed_action=action, mec_level=level, expected_preserve=preserve,
                expected_modify=modify, smaller_alternatives=smaller,
                evidence_refs=refs, confidence={'level':'MODERATE','rationale':'Evidence bounds mechanism/framework; synthetic facts fix comparator. Exact individual response remains unvalidated.'},
                conditions=['only this explicit synthetic profile/configuration','current independent scientific and governance review required','no real athlete prescription inferred','recheck at next relevant session or material new fact'],
                limits=['Not clinical/human/empirical validation','No universal hours, fatigue score, adherence percentage or progression cutoff'],
                must_not=['rewrite observed/completed history','replace missed training as debt','infer individual safety from null group findings','turn priority alone into necessity'],
                agency=BASE['agency'], re_review_trigger=['new symptoms/restrictions','new applicable evidence','changed goal/phase/intensity method/equipment','response outside accepted exemplar'])
    v.update(kw)
    return v

