def source(id,title,authors,year,url,doi,pmid,kind,access,pop,findings,locator,limits,counter):
    return dict(source_id=id,title=title,authors=authors,year=year,url=url,doi=doi,pmid=pmid,
       source_type=kind,access=access,accessed_on=DATE,verified=True,
       prescriptive_support_eligible=(access=='FULL_TEXT' and kind not in ['COMMENTARY_OPINION','ABSTRACT_ONLY_REPORT']),
       population_design_dose=pop,findings=findings,locator=locator,limitations=limits,counterevidence=counter)

