def readable(obj):
    if isinstance(obj,dict): return {k:readable(v) for k,v in obj.items()}
    if isinstance(obj,list): return [readable(v) for v in obj]
    if isinstance(obj,str):
        for old,new in sorted(READABILITY.items(), key=lambda kv:-len(kv[0])):
            obj=obj.replace(old,new)
    return obj

def all_variants():
    seen={}
    for c in CASES+EXTENSIONS:
        for v in c.get('variants',[]): seen[v['variant_id']]=v
        for w in c.get('level_witnesses',[]): seen[w['payload']['variant_id']]=w['payload']
    for v in SUPPLEMENTAL: seen[v['variant_id']]=v
    return list(seen.values())

def write_documents():
    header=f'**{REV} · AUTHOR_SUBMISSION · SSCTR-1.0.0 · {DATE}.**\n\nAll athlete states and doses are explicitly synthetic. Independent review, not this author, determines item approval. Foundation 0.2 remains candidate; runtime/Figma/clinical clearance are outside scope.\n'
    lines=['# G01 coverage matrix',header,'The internally reviewable subset covers regular, task-competent adults in five modes. It is an explicit review recipe library, not proof an executable product catalog exists. Beginner, special-population, specialized performance and clinical coverage are not inferred.','\n| Profile | Experience required | Exact review recipes | Bounded goal |','|---|---|---|---|']
    for p in PROFILES: lines.append('| '+p['mode']+' | '+str(p['experience_levels'])+' | '+', '.join(p['recipe_ids'])+' | '+p['supported_goals'][0]+' |')
    lines+=['\nEach row supplies an actual week, recipe-specific equipment requirements, positive witness and four negative branches in the JSON. Missing a required item blocks that recipe; an explicitly reviewed alternative can remain available. Running skill does not establish lifting skill, and the converse also holds.\n','Required inputs:\n']+['- '+x for x in INPUTS_REQUIRED]
    lines+=['\nClinical concern means persistent pain, injury/illness-related return, pathology, rehab or clearance dependency. Refer to the qualified clinical human; no lower dose replaces that review. Unknown eligibility alone means ASK/HOLD on the dependent prescription, not a diagnosis or blanket referral.\n','Concrete remaining gaps:\n']+['- **'+g['gap_id']+'** — '+g['scope']+': '+g['missing']+'. Owner: '+g['owner']+'.' for g in GAPS]
    lines+=['\nSources: '+', '.join('['+s['source_id']+']('+s['url']+')' for s in SOURCES[:4])+'. The sources constrain healthy-adult training and concurrent interpretation; they do not establish this product is effective or legally approved.']
    md('G01_COVERAGE_MATRIX.md','\n'.join(lines))
    lines=['# G02 policy registry',header,'The policy fields distinguish literature-supported boundaries, explicit programming intent, and unvalidated exact-dose effects. A proposed conditional approval is a request to the independent reviewer; it is not self-approval.','\n| ID | Submitted disposition | Rule |','|---|---|---|']
    for p in POLICIES: lines.append('| '+p['policy_id']+' | '+p['proposed_disposition']+' | '+p['rule']+' |')
    lines+=['\nConcrete review recipes:\n']
    for r in RECIPES: lines+=['- **'+r['recipe_id']+'** ('+r['proposed_disposition']+'): '+r['essential_stimulus']+'. '+r['limits']]
    lines+=['\nThe exact reduction for fatigue, exact return sequence, exact event taper and earned load step remain limited reversible candidates. No literature review validates a universally sufficient third-set omission, fixed number of return days, fixed taper percentage, or RIR/progression cutoff. The explicit numbers in the fixtures are test inputs and accepted programming choices, not population thresholds.']
    md('G02_POLICY_REGISTRY.md','\n'.join(lines))
    lines=['# Case reviews S01–S29',header,'The original eight QUESTIONABLE inputs remain frozen and incomplete. The successors below are separately versioned synthetic fixtures. A complete successor does not retroactively complete the source case.','\nS01/S02 differ only in priority; all three paired branches preserve that control. Both adequate branches KEEP. Both conflict branches retain the same valid move alternatives and ASK preference: no fabricated priority effect is required. S13/S14 differ only in accepted criticality/goal linkage; the prior key exposure is common to both.']
    for c in CASES:
        lines+=['\n## '+c['case_id']+' — '+c['title']+'\n']
        for v in c['variants']:
            lines+=['- **'+v['variant_id']+'** — '+v['proposed_disposition']+' / '+v['proposed_action']+'; MEC '+str(v['mec_level'])+'. '+v['branch']+'. Preserve: '+ '; '.join(v['expected_preserve'])+'. Modify: '+('; '.join(v['expected_modify']) or 'none')+'. Evidence '+', '.join(v['evidence_refs'])+'.']
        if c.get('remaining_gap'): lines+=['\nOpen: '+c['remaining_gap']]
    lines+=['\nGolden supplements: S06-HRV preserves an independently adequate week despite one divergent optional HRV observation; S09-MISS keeps the adequate remainder after a confirmed missed low-criticality session without debt replacement; SIL-S09-SUB uses the C4-L4 bilateral-task substitution boundary. No recommendation is a device delivery or performed fact.']
    md('CASE_REVIEWS_S01_S29.md','\n'.join(lines))
    lines=['# C1–C6 reviews',header,'The seven MEC witnesses use the installed conceptual levels exactly. They test control and programming intent under supplied premises; none is physiological gold simply because its wording is precise.']
    for c in EXTENSIONS:
        lines+=['\n## '+c['case_id']+' — '+c['title']+'\n']
        for v in c['variants']: lines+=['- **'+v['variant_id']+'** — '+v['proposed_disposition']+' / '+v['proposed_action']+'; MEC '+str(v['mec_level'])+'. '+v['branch']+'. '+('; '.join(v['expected_modify']) or 'No mutation')+'.']
        if c['case_id']=='C1':
            lines+=['\nChronological trajectory:']+['- '+x['snapshot_id']+' '+x['time']+': '+x['new_fact']+' → '+x['official']+'.' for x in c['snapshots']]
        if c['case_id']=='C4':
            lines+=['\n| AE level | Positive witness | Why the smaller effect is insufficient |','|---|---|---|']
            for w in c['level_witnesses']:
                v=w['payload'];lines+=['| '+str(w['level'])+' | '+v['variant_id']+' | '+'; '.join(x['candidate_id']+': '+x['reason'] for x in v['smaller_alternatives'])+' |']
        if c.get('remaining_gap'): lines+=['\nOpen: '+c['remaining_gap']]
    lines+=['\nAccepted source-audit corrections before submission: (1) split squats retain knee-extensor work, so Level4 uses explicit bilateral task linkage, not a missing-muscle assertion; (2) Level1 changes a currently fixed two-minute target and requires confirmation, while a preauthorized range would be Level0; (3) Level6 replaces current essential stimuli under the new goal and retains old stimuli only as history; (4) S28 has only pre-pause training in its ledger; (5) S13/S14 share the same prior-key exposure; (6) C1 second short night is retrospective disclosure, not a second night inside the same day; (7) limited reentry/taper recipes retain limited dispositions. These are author corrections, not independent gate results.']
    md('C1_C6_REVIEWS.md','\n'.join(lines))
    lines=['# Literature search log',header,'Access: web search and actual publisher/PubMed/PMC retrieval were available. No subscription, institutional access, live athlete data or empirical experiment. This focused review is not a systematic review; no formal GRADE/AMSTAR rating was performed.','\nExecuted searches on 2026-10-23:\n']
    for i,(q,purpose,result) in enumerate(SEARCHES,1): lines+=['- '+str(i)+'. `'+q+'` — '+purpose+'. '+result+'.']
    lines+=['\nActual read depth and source selection:\n']
    for s in SOURCES: lines+=['- **'+s['source_id']+' — '+s['access']+'**: ['+s['title']+']('+s['url']+'). Read: '+s['locator']+' Limits: '+'; '.join(s['limitations'])+'.']
    lines+=['\nCounterevidence was directed, not a vote count: Huiberts qualifies universal compatibility; acute Silva results do not imply chronic impairment; Hickmott qualifies universal autoregulation superiority; taper population limits prevent a generic recreational percentage; detraining/retraining evidence does not validate clinical return. Newer abstract-only Held/Huang are retained as auxiliary context, not decisive dose authorities.','\nAccess failures: PMC challenges occurred for Schumann, Huiberts, Saw and Huang pages; actual publisher full text resolved Schumann/Huiberts. Saw BJSM returned403; Huang publisher returned403. Their full text was not read. Wang/Currier PMC and Halonen/Hickmott/Silva publisher text were read in this instance. A malformed JavaScript search invocation failed before execution and contributed no search evidence. No challenge bypass or paid access claimed.','\nExclusions: generic blogs, social posts, commercial summaries and non-authoritative PDF mirrors were not used. Older-adult/eccentric cessation papers do not decide the exact14-day trained-hybrid return. Collegiate return consensus percentage rules were found but not transferred. Zhao2026 with linked correction remains excluded from decisive inference until the correction is read.','\nStop: the bounded scope/control policies can be reviewed with accessible evidence; more generic papers cannot create actual athlete facts or prove exact fatigue-reduction, concurrent-return or taper dose efficacy. Those concrete gaps remain numbered.']
    md('SEARCH_LOG.md','\n'.join(lines))

def write_decisions():
    records=[]
    searches=[dict(query=q,site='Web discovery followed by PubMed / actual publisher / PMC',searched_on=DATE,purpose=p,result_notes=r) for q,p,r in SEARCHES]
    source_map={s['source_id']:s for s in SOURCES}
    entries=[]
    for p in PROFILES:
        v=variant(p['profile_id'],'coverage definition and explicit configured witnesses',dict(population=p['population'],eligibility={'status':'SCOPE_DEFINITION_ONLY'},goals={'goal':p['supported_goals'][0]},planned_week=p['planned_week']),'NOT_APPLICABLE',None,['clinical boundary','recipe-specific coverage limits'],[],[{'candidate_id':'GENERALIZE','verdict':'REJECT','reason':'mode/ontology count not coverage proof'}],p['evidence_refs'])
        entries.append((v,'G01','G01_COVERAGE_MATRIX.json'))
    for v in all_variants():
        target='CASE_REVIEWS_S01_S29.json' if any(v['variant_id']==x['variant_id'] for c in CASES for x in c['variants']) or v in SUPPLEMENTAL else 'C1_C6_REVIEWS.json'
        entries.append((v,'G02',target))
    for v,gate,target in entries:
        estatus=v['facts'].get('eligibility',{}).get('status','NONCLINICAL_CONFIRMED')
        if estatus not in ['SCOPE_DEFINITION_ONLY','NONCLINICAL_CONFIRMED','ELIGIBILITY_UNASSESSED','CLINICAL_CONCERN']: estatus='ELIGIBILITY_UNASSESSED'
        proposed=v['proposed_disposition']
        # Authorship never self-approves. Proposed AWC is independently adjudicated elsewhere.
        disposition='LIMITED_REVERSIBLE_RECOMMENDATION' if proposed in ['APPROVE','APPROVE_WITH_CONDITIONS'] else proposed
        refs=v['evidence_refs'];sources=[source_map[x] for x in refs]
        evidence=v['evidence_status']
        decisive=next((s for s in sources if s['prescriptive_support_eligible']),None)
        claim_status='SUPPORTED_WITH_LIMITS' if decisive and evidence not in ['OUT_OF_SCOPE_CLINICAL','INSUFFICIENT_EVIDENCE','CONFLICTING_EVIDENCE','PLAUSIBLE_BUT_UNCERTAIN'] else evidence
        claims=[dict(claim_id=v['variant_id']+'-BOUNDS',statement='Applicable literature bounds the interpretation and prevents universal readiness, spacing, dose or outcome claims; it does not validate exact synthetic individual efficacy.',basis='INFERRED',role='DECISION_SUPPORT' if claim_status=='SUPPORTED_WITH_LIMITS' else 'CONTEXT',evidence_status=claim_status,source_ids=refs,applicability='Only the stated population/task/outcome/horizon and explicit limits.',limitations=v['limits'],counterevidence=['See linked source-level counterevidence; chronic group findings are not acute individual readiness.'])]
        if v['mec_level'] not in [None,0]: claims.append(dict(claim_id=v['variant_id']+'-DOSE',statement='The exact candidate delta is a synthetic programming/test exemplar; no empirical individual efficacy or universal optimal dose is established.',basis='DECIDED',role='OPEN_QUESTION',evidence_status='PLAUSIBLE_BUT_UNCERTAIN' if evidence!='OUT_OF_SCOPE_CLINICAL' else 'OUT_OF_SCOPE_CLINICAL',source_ids=refs,applicability='No transfer beyond this explicitly bounded candidate.',limitations=['Independent review cannot turn a test premise into measured physiology.'],counterevidence=['Smaller alternatives and task specificity may invalidate the exact dose.']))
        smaller='; '.join(x['candidate_id']+': '+x['reason'] for x in v['smaller_alternatives'])
        answers=[
           'Current plan is adequate under supplied facts.' if v['proposed_action']=='KEEP' else 'Current exact target is infeasible, challenged or unresolved for this bounded branch; see candidate comparator. ',
           str(v['facts'].get('new_material_fact',v['facts'].get('execution',v['facts'].get('interruption',v['branch'])))),
           'KEEP is sufficient; no material mutation needed.' if v['proposed_action']=='KEEP' else 'KEEP is assessed explicitly: '+smaller,
           'NOT_REQUIRED.' if v['proposed_action']=='KEEP' else ('UNDETERMINATE; ASK/HOLD dependent scope.' if v['proposed_action'] in ['ASK','HOLD','CLINICAL_HUMAN_REQUIRED'] else 'Required only for the supplied intent/feasibility premise; exact physiological effect remains bounded/uncertain.'),
           'Candidate MEC '+str(v['mec_level'])+': '+('; '.join(v['expected_modify']) or 'none'),
           smaller,
           'Priority '+str(v['facts'].get('priority_mode','scope definition'))+'; preserve '+ '; '.join(v['expected_preserve']),
           'Evidence '+evidence+'; refs '+','.join(refs)+'. Exact dose effects and scope limits are distinct from control intent.',
           '; '.join(v['limits'])+' '+('; '.join(v['conditions'])),
           'Route '+v['proposed_action']+'; agency: '+v['agency']]
        path='reviews/sports-domain-closure/2026-10-23/scientific/'+target
        records.append(dict(schema_version='1.0.0',review_id='SDC-'+v['variant_id'],review_revision=REV,review_date=DATE,agent_version='SSCTR-1.0.0',constitution_revision='SSCTR-CONST-1.0.0',protocol_revision='SSCTR-EP-1.0.0',
          reviewer=dict(actor_type='AI_AGENT',instance_id=INSTANCE,human_credentials_claimed=False,independent_of_target_author=False),
          target=dict(project='MyApp / Vilumo Fit',artifact=path,artifact_revision=REV,sha256=hashlib.sha256((ROOT/path).read_bytes()).hexdigest(),rule_ids=[v['variant_id']]),
          question='AUTHOR_SUBMISSION: independently assess proposed '+proposed+' for '+v['variant_id']+' — '+v['branch'],
          population_context=dict(population=str(v['facts'].get('population','explicit synthetic adult nonclinical fixture; clinical branch if stated')),eligibility_status=estatus,facts=['Explicit synthetic fixture '+v['variant_id']+' in target JSON; no real participant.','Resolved state and recipe references retained in target; immutable originals unchanged.'],unknowns=[] if estatus in ['SCOPE_DEFINITION_ONLY','NONCLINICAL_CONFIRMED'] else ['dependent eligibility/clinical boundary unresolved']),
          scope=dict(gate=gate,item_ids=[v['variant_id']],prescriptive_impact=True,whole_gate_closure=False),
          literature_snapshot=dict(as_of=DATE,searches=searches,sources=sources,counterevidence_search='Directed contrary/context searches and actual source limits are in SEARCH_LOG; no vote-counting or universal absent-evidence safety inference.'),
          claims=claims,evidence_status=evidence,applicability='Only the target synthetic profile, task configuration, accepted goal linkage and horizon; no runtime catalog, service-model, clinical or empirical approval.',
          disposition=disposition,proposed_action=v['proposed_action'],decision=dict(rationale='Author proposal '+proposed+' pending independent review. '+v['branch']+'. '+smaller,preserve=v['expected_preserve'],modify=v['expected_modify'],mec_change_level=str(v['mec_level']) if v['mec_level'] is not None else 'NOT_APPLICABLE / INFORMATION_OR_CLINICAL_CONTROL',trade_off='; '.join(v['expected_modify']) or 'No material plan tradeoff; current adequate intent retained.',must_not=v['must_not'],conditions=v['conditions']),
          confidence=v['confidence'],limitations=v['limits']+['Author submission; cannot approve own target. Proposed approval field is not actual approval.'],
          ae_review=dict(applicable=gate=='G02',answers=[dict(question_number=i+1,answer=str(a)) for i,a in enumerate(answers)] if gate=='G02' else [],not_applicable_reason=None if gate=='G02' else 'Coverage definition, not an adaptive athlete decision.'),
          governance=dict(gate_status='NOT_CLOSED_BY_THIS_RECORD',publication_status='NOT_PUBLISHED',human_validation=False,empirical_product_validation=False,clinical_clearance=False,next_owner='Independent SSCTR source/policy reviewer and governance judge, then Chief',next_action='Review exact target hash; issue independent disposition separately; queue every accepted prescriptive approval in the existing funded-human queue.'),
          expiry=dict(owner='SSCTR / Chief',review_by=None,event_based_expiry='Material source/population/goal/recipe/input/authority change invalidates dependent proposal.',triggers=v['re_review_trigger']+['adverse event or runtime inconsistency','Founder declares sufficient funding for qualified-human revalidation']),
          human_revalidation=dict(state='NOT_APPROVED_PRESCRIPTIVE_DECISION',queue_ref=None,human_review=None),supersedes=None,dependent_items=[v['variant_id']]))
    dump('DECISIONS.json',envelope('AUTHOR_SCIENTIFIC_DECISIONS',records=records,
       proposed_approvals_live_in='Target JSON proposed_disposition; author never self-approves',
       future_queue='Existing reviews/provisional-sports-science/2026-10-23/HUMAN_REVALIDATION_QUEUE.json; Chief appends only independently accepted prescriptive approvals'))

# Consistent successor context: the original 24km report is not silently reused as
# a complete two-run week, and taper20min is not the separate reentry recipe.
BASE['goals']['running']='recreational controlled-running continuity over 8 weeks; no promised race result or specialized peak'
BASE['history']['run_total_each_week_km']=[11,12,12]
for r in RECIPES:
    if r['recipe_id']=='R-TAPER10K':r['dose']['days_before_event']['D-6']='20 min familiar easy exposure for C5 only; no R28 reentry recipe inheritance'

if __name__ == '__main__':
    RECIPES=readable(RECIPES); BASE=readable(BASE); CASES=readable(CASES); EXTENSIONS=readable(EXTENSIONS); SUPPLEMENTAL=readable(SUPPLEMENTAL); POLICIES=readable(POLICIES); PROFILES=readable(PROFILES); GAPS=readable(GAPS); SOURCES=readable(SOURCES); SEARCHES=readable(SEARCHES)
    write_all()
